/**
 * Synthetic datasets used ONLY by the held-out evaluation (never referenced by the NL2SQL engine).
 * Everything is generated by a seeded PRNG, so the data — and therefore every gold answer — is reproducible.
 *
 *   HR     → uploaded as ONE .sql file (pg_dump style: `public.` prefixes, INSERT … VALUES, FKs added with ALTER TABLE)
 *   Sales  → uploaded as six .csv files (no constraints: relationships must be suggested, then confirmed)
 */

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const pad = (n: number) => String(n).padStart(2, "0");
const isoDate = (d: Date) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const dayMs = 86_400_000;
const between = (rnd: () => number, from: string, to: string) => {
  const a = Date.parse(`${from}T00:00:00Z`);
  const b = Date.parse(`${to}T00:00:00Z`);
  return new Date(a + Math.floor(rnd() * ((b - a) / dayMs + 1)) * dayMs);
};
const pick = <T>(rnd: () => number, xs: readonly T[]): T => xs[Math.floor(rnd() * xs.length)];
const sqlText = (s: string) => `'${s.replace(/'/g, "''")}'`;

// ───────────────────────────────────────── HR ─────────────────────────────────────────

export interface HrData {
  departments: { id: number; name: string; location: string }[];
  jobTitles: { id: number; title: string; level: string }[];
  employees: { id: number; fullName: string; email: string; departmentId: number; jobTitleId: number; hireDate: string; status: string }[];
  salaries: { id: number; employeeId: number; amount: number; effectiveDate: string }[];
  leaveRequests: { id: number; employeeId: number; leaveType: string; startDate: string; endDate: string; status: string }[];
}

const FIRST = ["Ada", "Boris", "Chloe", "Dmitri", "Elena", "Farid", "Grace", "Hugo", "Ines", "Jonas", "Katya", "Liam", "Mira", "Nils", "Olga", "Pavel", "Quinn", "Rosa", "Sven", "Tara", "Umar", "Vera", "Wim", "Xenia", "Yusuf", "Zoe"];
const LAST = ["Andersen", "Becker", "Costa", "Dubois", "Eriksen", "Fischer", "Garcia", "Haas", "Ivanov", "Jensen", "Kovacs", "Lopez", "Moreau", "Novak", "O'Brien", "Petrov", "Rossi", "Schmidt", "Tanaka", "Ulrich", "Varga", "Weber", "Yilmaz", "Zielinski"];

export function generateHr(): HrData {
  const rnd = mulberry32(20260921);
  const departments = [
    { id: 1, name: "Engineering", location: "Berlin" },
    { id: 2, name: "Sales", location: "Paris" },
    { id: 3, name: "Marketing", location: "Madrid" },
    { id: 4, name: "Finance", location: "Berlin" },
    { id: 5, name: "Human Resources", location: "Paris" },
    { id: 6, name: "Operations", location: "Rome" },
  ];
  const jobTitles = [
    { id: 1, title: "Software Engineer", level: "mid" },
    { id: 2, title: "Senior Software Engineer", level: "senior" },
    { id: 3, title: "Junior Developer", level: "junior" },
    { id: 4, title: "Sales Representative", level: "mid" },
    { id: 5, title: "Sales Manager", level: "senior" },
    { id: 6, title: "Marketing Specialist", level: "mid" },
    { id: 7, title: "Financial Analyst", level: "mid" },
    { id: 8, title: "Accountant", level: "junior" },
    { id: 9, title: "HR Generalist", level: "mid" },
    { id: 10, title: "Recruiter", level: "junior" },
    { id: 11, title: "Operations Coordinator", level: "mid" },
    { id: 12, title: "Operations Director", level: "lead" },
  ];
  const titlesFor: Record<number, number[]> = { 1: [1, 2, 3], 2: [4, 5], 3: [6], 4: [7, 8], 5: [9, 10], 6: [11, 12] };
  const headcount: Record<number, number> = { 1: 24, 2: 16, 3: 8, 4: 8, 5: 6, 6: 10 };
  const baseSalary: Record<number, number> = { 1: 78000, 2: 105000, 3: 52000, 4: 48000, 5: 82000, 6: 56000, 7: 64000, 8: 47000, 9: 54000, 10: 44000, 11: 50000, 12: 110000 };

  const usedNames = new Set<string>();
  const usedHire = new Set<string>();
  const usedSalary = new Set<number>();
  const employees: HrData["employees"] = [];
  const salaries: HrData["salaries"] = [];
  let id = 0;
  for (const dept of departments) {
    for (let i = 0; i < headcount[dept.id]; i++) {
      id++;
      let fullName: string;
      do fullName = `${pick(rnd, FIRST)} ${pick(rnd, LAST)}`;
      while (usedNames.has(fullName));
      usedNames.add(fullName);
      let hire: string;
      do hire = isoDate(between(rnd, "2015-01-01", "2024-06-30"));
      while (usedHire.has(hire));
      usedHire.add(hire);
      const jobTitleId = pick(rnd, titlesFor[dept.id]);
      let amount = baseSalary[jobTitleId] + Math.floor(rnd() * 20) * 500;
      while (usedSalary.has(amount)) amount += 50;
      usedSalary.add(amount);
      employees.push({
        id,
        fullName,
        email: `${fullName.toLowerCase().replace(/[^a-z]+/g, ".")}@example.test`,
        departmentId: dept.id,
        jobTitleId,
        hireDate: hire,
        status: rnd() < 0.85 ? "active" : "on_leave",
      });
      salaries.push({ id, employeeId: id, amount, effectiveDate: isoDate(between(rnd, "2022-01-01", "2024-09-30")) });
    }
  }
  const leaveRequests: HrData["leaveRequests"] = [];
  for (let i = 1; i <= 96; i++) {
    const start = between(rnd, "2023-01-01", "2024-08-31");
    const len = 1 + Math.floor(rnd() * 14);
    const r = rnd();
    leaveRequests.push({
      id: i,
      employeeId: 1 + Math.floor(rnd() * employees.length),
      leaveType: pick(rnd, ["annual", "sick", "parental", "unpaid"] as const),
      startDate: isoDate(start),
      endDate: isoDate(new Date(start.getTime() + len * dayMs)),
      status: r < 0.7 ? "approved" : r < 0.85 ? "pending" : "rejected",
    });
  }
  return { departments, jobTitles, employees, salaries, leaveRequests };
}

/** The HR dataset as a pg_dump-style SQL file. */
export function hrSql(d: HrData = generateHr()): string {
  const values = (rows: string[][]) => rows.map((r) => `  (${r.join(", ")})`).join(",\n");
  return `--
-- PostgreSQL database dump (synthetic HR sample)
--
SET client_encoding = 'UTF8';

CREATE TABLE public.departments (
    id integer NOT NULL PRIMARY KEY,
    name text NOT NULL,
    location text
);

CREATE TABLE public.job_titles (
    id integer NOT NULL PRIMARY KEY,
    title text NOT NULL,
    level text NOT NULL
);

CREATE TABLE public.employees (
    id integer NOT NULL PRIMARY KEY,
    full_name text NOT NULL,
    email text,
    department_id integer NOT NULL,
    job_title_id integer NOT NULL,
    hire_date date NOT NULL,
    status text NOT NULL,
    CONSTRAINT employees_status_check CHECK (status IN ('active', 'on_leave'))
);

CREATE TABLE public.salaries (
    id integer NOT NULL PRIMARY KEY,
    employee_id integer NOT NULL UNIQUE,
    amount numeric(10,2) NOT NULL,
    effective_date date NOT NULL
);

CREATE TABLE public.leave_requests (
    id integer NOT NULL PRIMARY KEY,
    employee_id integer NOT NULL,
    leave_type text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text NOT NULL
);

INSERT INTO public.departments (id, name, location) VALUES
${values(d.departments.map((x) => [String(x.id), sqlText(x.name), sqlText(x.location)]))};

INSERT INTO public.job_titles (id, title, level) VALUES
${values(d.jobTitles.map((x) => [String(x.id), sqlText(x.title), sqlText(x.level)]))};

INSERT INTO public.employees (id, full_name, email, department_id, job_title_id, hire_date, status) VALUES
${values(d.employees.map((x) => [String(x.id), sqlText(x.fullName), sqlText(x.email), String(x.departmentId), String(x.jobTitleId), sqlText(x.hireDate), sqlText(x.status)]))};

INSERT INTO public.salaries (id, employee_id, amount, effective_date) VALUES
${values(d.salaries.map((x) => [String(x.id), String(x.employeeId), x.amount.toFixed(2), sqlText(x.effectiveDate)]))};

INSERT INTO public.leave_requests (id, employee_id, leave_type, start_date, end_date, status) VALUES
${values(d.leaveRequests.map((x) => [String(x.id), String(x.employeeId), sqlText(x.leaveType), sqlText(x.startDate), sqlText(x.endDate), sqlText(x.status)]))};

ALTER TABLE ONLY public.employees ADD CONSTRAINT employees_department_fk FOREIGN KEY (department_id) REFERENCES public.departments(id);
ALTER TABLE ONLY public.employees ADD CONSTRAINT employees_job_title_fk FOREIGN KEY (job_title_id) REFERENCES public.job_titles(id);
ALTER TABLE ONLY public.salaries ADD CONSTRAINT salaries_employee_fk FOREIGN KEY (employee_id) REFERENCES public.employees(id);
ALTER TABLE ONLY public.leave_requests ADD CONSTRAINT leave_requests_employee_fk FOREIGN KEY (employee_id) REFERENCES public.employees(id);

CREATE INDEX idx_employees_department ON public.employees USING btree (department_id);
CREATE INDEX idx_leave_requests_employee ON public.leave_requests USING btree (employee_id);
`;
}

// ───────────────────────────────────────── Sales / inventory ─────────────────────────────────────────

export interface SalesData {
  customers: { id: number; name: string; email: string; city: string; country: string; signupDate: string }[];
  categories: { id: number; name: string }[];
  products: { id: number; name: string; categoryId: number; unitPrice: number; cost: number }[];
  orders: { id: number; customerId: number; orderDate: string; status: string }[];
  orderItems: { id: number; orderId: number; productId: number; quantity: number; unitPrice: number }[];
  inventory: { id: number; productId: number; warehouse: string; quantityOnHand: number; reorderLevel: number }[];
}

const CITIES: [string, string][] = [["Berlin", "Germany"], ["Munich", "Germany"], ["Paris", "France"], ["Lyon", "France"], ["Madrid", "Spain"], ["Milan", "Italy"], ["London", "United Kingdom"]];
const CUSTOMER_FIRST = ["Alma", "Bruno", "Carla", "Dario", "Emil", "Fiona", "Gustav", "Hanna", "Ivo", "Julia", "Karl", "Lena", "Marco", "Nora", "Otto", "Petra", "Rafael", "Sofia", "Tomas", "Ulla"];
const CUSTOMER_LAST = ["Alvarez", "Berg", "Conti", "Durand", "Ebner", "Ferrari", "Grimm", "Hoffmann", "Jansen", "Klein", "Lang", "Meyer", "Neumann", "Ortiz", "Pohl", "Richter", "Simon", "Thomas"];

/** Chosen (from a seed search over data properties only) so that every top-N / max question has a tie-free answer. */
export const SALES_SEED = 1;

export function generateSales(seed: number = SALES_SEED): SalesData {
  const rnd = mulberry32(seed);
  const categories = [{ id: 1, name: "Electronics" }, { id: 2, name: "Home & Garden" }, { id: 3, name: "Toys" }, { id: 4, name: "Books" }, { id: 5, name: "Sports" }];
  const productNames: [string, number, number][] = [
    ["Wireless Headphones", 1, 79.9], ["USB-C Charger, 65W", 1, 34.5], ["Smart Speaker", 1, 59], ["Action Camera", 1, 149],
    ["Ceramic Plant Pot", 2, 18.75], ["LED Desk Lamp", 2, 27.4], ["Garden Hose 20m", 2, 32], ["Storage Box \"Nordic\"", 2, 14.2],
    ["Wooden Puzzle", 3, 21], ["Building Blocks Set", 3, 39.9], ["Remote Control Car", 3, 46.5], ["Plush Bear", 3, 12.3],
    ["Cooking for Beginners", 4, 19.9], ["History of Europe", 4, 24.5], ["Data Science Handbook", 4, 44], ["Children's Atlas", 4, 16.8],
    ["Yoga Mat", 5, 22.5], ["Trail Running Shoes", 5, 89], ["Water Bottle 1L", 5, 9.9], ["Resistance Bands", 5, 13.4],
  ];
  const products = productNames.map(([name, categoryId, unitPrice], i) => ({ id: i + 1, name, categoryId, unitPrice, cost: Math.round(unitPrice * (0.5 + rnd() * 0.2) * 100) / 100 }));

  const usedNames = new Set<string>();
  const customers: SalesData["customers"] = [];
  for (let i = 1; i <= 40; i++) {
    let name: string;
    do name = `${pick(rnd, CUSTOMER_FIRST)} ${pick(rnd, CUSTOMER_LAST)}`;
    while (usedNames.has(name));
    usedNames.add(name);
    const [city, country] = pick(rnd, CITIES);
    customers.push({ id: i, name, email: `${name.toLowerCase().replace(/[^a-z]+/g, ".")}@example.test`, city, country, signupDate: isoDate(between(rnd, "2022-01-01", "2024-06-30")) });
  }

  const orders: SalesData["orders"] = [];
  for (let i = 1; i <= 150; i++) {
    const r = rnd();
    // customers are drawn with a skew so that "best customers" have distinct order counts
    const customerId = 1 + Math.floor(Math.pow(rnd(), 1.6) * customers.length);
    orders.push({ id: i, customerId, orderDate: isoDate(between(rnd, "2023-01-01", "2024-12-31")), status: r < 0.6 ? "completed" : r < 0.8 ? "shipped" : r < 0.9 ? "pending" : "cancelled" });
  }
  const orderItems: SalesData["orderItems"] = [];
  let itemId = 0;
  for (const o of orders) {
    const lines = 1 + Math.floor(rnd() * 3);
    const chosen = new Set<number>();
    for (let k = 0; k < lines; k++) {
      const p = products[Math.floor(Math.pow(rnd(), 1.4) * products.length)];
      if (chosen.has(p.id)) continue;
      chosen.add(p.id);
      orderItems.push({ id: ++itemId, orderId: o.id, productId: p.id, quantity: 1 + Math.floor(rnd() * 5), unitPrice: p.unitPrice });
    }
  }
  const inventory: SalesData["inventory"] = [];
  let invId = 0;
  for (const p of products) {
    for (const warehouse of ["Berlin", "Lyon"]) {
      const reorderLevel = 10 + Math.floor(rnd() * 20);
      inventory.push({ id: ++invId, productId: p.id, warehouse, reorderLevel, quantityOnHand: Math.floor(rnd() * 60) });
    }
  }
  return { customers, categories, products, orders, orderItems, inventory };
}

const csvCell = (v: string | number) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = (header: string[], rows: (string | number)[][]) => [header.join(","), ...rows.map((r) => r.map(csvCell).join(","))].join("\n") + "\n";

export function salesCsvFiles(d: SalesData = generateSales()): { name: string; text: string }[] {
  return [
    { name: "customers.csv", text: csv(["id", "name", "email", "city", "country", "signup_date"], d.customers.map((c) => [c.id, c.name, c.email, c.city, c.country, c.signupDate])) },
    { name: "categories.csv", text: csv(["id", "name"], d.categories.map((c) => [c.id, c.name])) },
    { name: "products.csv", text: csv(["id", "name", "category_id", "unit_price", "cost"], d.products.map((p) => [p.id, p.name, p.categoryId, p.unitPrice, p.cost])) },
    { name: "orders.csv", text: csv(["id", "customer_id", "order_date", "status"], d.orders.map((o) => [o.id, o.customerId, o.orderDate, o.status])) },
    { name: "order_items.csv", text: csv(["id", "order_id", "product_id", "quantity", "unit_price"], d.orderItems.map((i) => [i.id, i.orderId, i.productId, i.quantity, i.unitPrice])) },
    { name: "inventory.csv", text: csv(["id", "product_id", "warehouse", "quantity_on_hand", "reorder_level"], d.inventory.map((i) => [i.id, i.productId, i.warehouse, i.quantityOnHand, i.reorderLevel])) },
  ];
}

/** Relationships a careful human would declare for the sales CSVs. Used to score the importer's SUGGESTIONS (precision / recall). */
export const SALES_EXPECTED_RELATIONSHIPS = [
  "orders.customer_id→customers.id",
  "products.category_id→categories.id",
  "order_items.order_id→orders.id",
  "order_items.product_id→products.id",
  "inventory.product_id→products.id",
];
